    ["مثال: أحمد محمد","Example: Ahmed Mohammed"],["مثال: ahmad أو cashier1","Example: ahmad or cashier1"],["مالك المنشأة","Business Owner"],["الحساب الحالي","Current Account"],["كلمة المرور يجب أن تحتوي على 8 أحرف على الأقل","Password must contain at least 8 characters"],["يرجى إدخال اسم المستخدم","Enter the username"],["يرجى إدخال اسم مستخدم صحيح","Enter a valid username"],["البريد الإلكتروني غير صحيح","The email address is invalid"],["اسم المستخدم مستخدم بالفعل","This username is already in use"],["البريد الإلكتروني مستخدم بالفعل","This email address is already in use"],["يرجى إدخال كلمة مرور للمستخدم","Enter a password for the user"],["المستخدم غير موجود.","User not found."],["تم تحديث المستخدم وكلمة المرور","User and password updated"],["تم تحديث المستخدم والصلاحيات","User and permissions updated"],["لم يسجل الدخول بعد","Has not signed in yet"],["تم إنشاء المستخدم وأصبح جاهزاً للدخول","User created and ready to sign in"],["تعذر حفظ المستخدم","Unable to save the user"],["تعديل المستخدم والصلاحيات","Edit User & Permissions"],["كلمة مرور جديدة - اختياري","New Password — Optional"],["تم تفعيل المستخدم","User activated"],["تم إيقاف المستخدم","User deactivated"],["تأكيد حذف المستخدم","Confirm user deletion"],["من قائمة مستخدمي VAREX","from the VAREX user list"],["تم حذف المستخدم","User deleted"],
    ["لم يتم العثور على البريد الإلكتروني","Email address not found"],["تعذر العثور على البريد الإلكتروني المطلوب تأكيده. يرجى العودة إلى صفحة إنشاء الحساب وإعادة المحاولة.","Unable to find the email address to verify. Return to the account creation page and try again."],["تعذر العثور على البريد الإلكتروني. يرجى العودة إلى صفحة إنشاء الحساب.","Unable to find the email address. Return to the account creation page."],["يرجى إدخال رمز التحقق المكوّن من 6 أرقام.","Enter the 6-digit verification code."],["وظيفة تأكيد البريد غير موجودة في ملف varex.js.","The email verification function is missing from varex.js."],["جاري تأكيد الحساب...","Verifying account..."],["رمز التحقق غير صحيح أو انتهت صلاحيته.","The verification code is incorrect or expired."],["حدث خطأ أثناء تأكيد الحساب.","An error occurred while verifying the account."],["يمكنك إعادة الإرسال بعد","You can resend after"],["ثانية","Seconds"],["تعذر تشغيل خدمة إعادة إرسال رمز التحقق.","Unable to start the code resend service."],["جاري الإرسال...","Sending..."],["تعذر إعادة إرسال رمز التحقق.","Unable to resend the verification code."],["تم إرسال رمز تحقق جديد إلى بريدك الإلكتروني.","A new verification code was sent to your email."],["حدث خطأ أثناء إعادة إرسال رمز التحقق.","An error occurred while resending the verification code."],["مبيعات","Sales"],["مشتريات","Purchases"],["مرتجعات","Returns"]
